import json
# construct 28x28 grid: 6x6 cells separated by 8; interior widths/heights 4, except final 3
bounds=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
g=[[0]*28 for _ in range(28)]
for i in [4,9,14,19,24]:
    g[i]=[8]*28
    for r in range(28): g[r][i]=8
for ri,(a,b) in enumerate(bounds):
 for ci,(x,y) in enumerate(bounds):
  color = 6 if ri==1 and ci==2 else (2 if ri==1 or ci==0 else (3 if ci==2 else 0))
  for r in range(a,b):
   for c in range(x,y): g[r][c]=color
print(json.dumps(g))
